// Verus specifications for the Fibonacci function
#[verifier::spec]
fn fibonacci(n: usize) -> Vec<i32> {
    // Precondition: n must be at least 2 to generate a Fibonacci sequence
    // Ensures: The returned vector contains the first n Fibonacci numbers
    // Requires: n >= 2
    // Ensures: fib_sequence.len() == n
    // Ensures: forall i: usize :: 0 <= i < n ==> fib_sequence[i] == fibonacci_number(i)
    // where fibonacci_number(i) is defined as:
    //   if i == 0 then 0
    //   else if i == 1 then 1
    //   else fibonacci_number(i - 1) + fibonacci_number(i - 2)
    #[verifier::requires(n >= 2)]
    #[verifier::ensures(|fib_sequence| fib_sequence.len() == n)]
    #[verifier::ensures(|fib_sequence| {
        (0..n).all(|i| {
            if i == 0 {
                fib_sequence[i] == 0
            } else if i == 1 {
                fib_sequence[i] == 1
            } else {
                fib_sequence[i] == fib_sequence[i - 1] + fib_sequence[i - 2]
            }
        })
    })]
    let mut fib_sequence = vec![0, 1]; // Start with the first two Fibonacci numbers

    // Invariant: At the start of each iteration, fib_sequence contains the first i Fibonacci numbers
    // Decreases: n - i
    #[verifier::invariant(fib_sequence.len() == i)]
    #[verifier::decreases(n - i)]
    for i in 2..n {
        let next_fib = fib_sequence[i - 1] + fib_sequence[i - 2]; // Calculate the next Fibonacci number
        fib_sequence.push(next_fib); // Add it to the sequence
    }

    fib_sequence // Return the complete Fibonacci sequence
}

